window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["0c"]={"https://www.gov.uk/foreign-travel-advice/central-african-republic":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"3ec734c098f9dfb268eb15fcb2903044c4f04173d16bca9775d7b7968497b74f","read":"https://www.gov.uk/api/content/foreign-travel-advice/central-african-republic","bytes":50719,"x":"fulltext v1","title":"Central African Republic travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-25T00:00:00+00:00","mod":"2026-05-28T12:08:37+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"p","s":["FCDO advises against all travel to the whole of the Central African Republic, including the areas of Bimbo, Begoua and Coline, except to the capital, Bangui."]},{"k":"p","s":["FCDO advises against all but essential travel to Bangui, including Bangui M’Poko International Airport."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/central-african-republic/safety-and-security"],"."]},{"k":"h","s":["Limited consular support"]},{"k":"p","s":["There is no British Embassy in the Central African Republic, and consular support is severely limited. The ",["British Embassy in Kinshasa, Democratic Republic of Congo","https://www.gov.uk/world/organisations/british-embassy-kinshasa"],", can provide limited remote consular support to British nationals."]},{"k":"h","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/central-african-republic/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of current rules for the most common types of travel."]},{"k":"p","s":["The authorities in the Central African Republic set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Central African Republic Embassy in Paris","https://paris.diplomatie.gouv.cf/"]," (in French)."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter the Central African Republic, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit the Central African Republic."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["Apply for a visa through the ",["Central African Republic Embassy in Paris","https://paris.diplomatie.gouv.cf/"]," (in French). Requirements can change at short notice, contact the Central African Republic Embassy in Paris for the latest requirements."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To pass border control in the Central African Republic, you must have a certificate to prove you’ve had a yellow fever vaccination."]},{"k":"p","s":["For more details about health entry requirements and recommended vaccinations for the Central African Republic, see ",["TravelHealthPro’s Central African Republic guide","https://travelhealthpro.org.uk/country/46/central-african-republic#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of the Central African Republic","https://edouanes.cf/?lang=en"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"p","s":["There is an export tax on cultural artefacts."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in the Central African Republic"]},{"k":"p","s":["Although there’s no recent history of terrorism in the Central African Republic, attacks cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate including in places visited by foreign nationals. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Current President Faustin-Archange Touadéra came to power through an election in 2015 and was re-elected in 2020. In August 2023, a constitutional referendum was passed, which included the removal of presidential term limits. Presidential elections are due in 2025."]},{"k":"p","s":["Protests, marches and demonstrations can happen with little notice and have encountered a strong police and security force presence. Protests have previously resulted in deaths and injuries. Protests have taken place in front of Western embassies as well as areas of political significance in the capital. If you are near any protests, marches or demonstrations, you should leave the area immediately. Stay alert and follow the local news, as the atmosphere can change quickly and without warning. Stay away from any blockades set up by the police and security forces."]},{"k":"p","s":["If the authorities suspect you of engaging and supporting activities that break the law in Central African Republic, you could be detained."]},{"k":"h","s":["Security situation"]},{"k":"p","s":["Tensions remain high following decades of violence between the Central African Republic government and rebel groups. The security situation could worsen without notice."]},{"k":"p","s":["Outside of Bangui, security conditions are extremely unstable. Armed groups continue to occupy areas in the north and south east of the country. Government services are limited outside of Bangui. There are ongoing incidents of armed conflict, banditry and hostage-taking."]},{"k":"p","s":["Outside of Bangui there are frequent cases of:"]},{"k":"li","s":["homicides"]},{"k":"li","s":["looting"]},{"k":"li","s":["criminal kidnapping"]},{"k":"li","s":["house burglary"]},{"k":"li","s":["unlawful detention"]},{"k":"li","s":["gunfire"]},{"k":"li","s":["carjacking"]},{"k":"p","s":["Attacks are unpredictable and have taken place against UN peacekeepers, humanitarian workers and foreign mining companies. There are unidentified improvised explosive devices in the north west of the country."]},{"k":"p","s":["Security conditions in Bangui are more stable with a significant presence of security forces, but could deteriorate rapidly."]},{"k":"p","s":["If you decide to remain in the Central African Republic against FCDO advice, you should have confidence in your security arrangements and maintain a high level of vigilance, especially outside of Bangui."]},{"k":"hs","s":["Armed patrols and roadblocks"]},{"k":"p","s":["Government security forces, UN peacekeepers, rebel groups and militias conduct armed patrols across the Central African Republic, including in Bangui. Armed personnel control roadblocks (both official and illegal) where you may be asked for a bribe. Take particular care when approaching these. Travel in groups if possible and avoid travelling at night."]},{"k":"p","s":["It is common for the police and armed groups to arbitrarily search and detain people, mainly Central African nationals but also foreign nationals."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Theft and robbery are common, and armed gangs operate in the outlying areas of Bangui, especially in the PK5 district. Bandits often target foreign nationals, including humanitarian workers. Weapons are common and can cause normal disputes in establishments such as bars to escalate quickly."]},{"k":"p","s":["Be alert to the risk of street crime, armed robbery and bribery at all times.Take care around:"]},{"k":"li","s":["government buildings"]},{"k":"li","s":["military sites"]},{"k":"li","s":["hotels"]},{"k":"li","s":["restaurants"]},{"k":"li","s":["bars"]},{"k":"p","s":["You can take precautions such as:"]},{"k":"li","s":["taking professional security advice"]},{"k":"li","s":["travelling in pre-arranged transport with trusted operators"]},{"k":"li","s":["not taking valuables or wearing jewellery in public"]},{"k":"li","s":["not walking alone at any time, especially at night"]},{"k":"li","s":["keeping valuables in a safe location"]},{"k":"li","s":["keeping copies of documents, including your passport"]},{"k":"li","s":["staying away from isolated areas"]},{"k":"hs","s":["Violent attacks in remote areas"]},{"k":"p","s":["Armed groups and bandits have used illegal roadblocks and have indiscriminately attacked travellers in remote areas. The attackers have burnt or stolen vehicles, and injured, kidnapped or killed passengers."]},{"k":"p","s":["Always keep vehicle and personal identification documents with you while travelling by road. Lock vehicle doors, keep windows closed and avoid driving off main routes. Medical help in the event of an accident is likely to be limited."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["You must always carry ID by law, such as a certified copy of your passport or a residence permit. The police can detain you if you do not have ID with you."]},{"k":"hs","s":["Buying diamonds"]},{"k":"p","s":["It is only legal to buy diamonds or precious stones through government-authorised agents."]},{"k":"hs","s":["Illegal drugs penalties"]},{"k":"p","s":["There are severe penalties for drug use and possession. If convicted, you can expect heavy fines and a long jail sentence."]},{"k":"hs","s":["Using cameras"]},{"k":"p","s":["You often need permission to take photos in public places. You may be detained, fined and have your camera confiscated for photographing government property, uniformed law enforcement officers or military installations and personnel."]},{"k":"p","s":["It is not permitted to take photographs the authorities think damage the country’s image (for example, street children and people with disabilities)."]},{"k":"p","s":["You can get a permit for more serious photography from the Ministry of Tourism."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["While homosexuality is not illegal, same-sex relationships are not widely accepted in Central African society. LGBT+ travellers may face arrest for “public expressions of love”."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Money"]},{"k":"p","s":["It is easier to exchange euros for Central African francs rather than US dollars. You can exchange traveller’s cheques at banks."]},{"k":"p","s":["There are very few ATMs. Most places, including hotels, do not accept international credit or debit cards."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in the Central African Republic, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["Roads are in extremely poor condition, especially in the rainy season from May to November. Most roads are unpaved, may close at short notice and require a 4-wheel-drive vehicle. Outside of Bangui, there are very few roads."]},{"k":"p","s":["You’ll need to have both the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience or a higher minimum age."]},{"k":"p","s":["Keep a private supply of fuel, food and drink if possible, especially if you are travelling any distance outside of Bangui."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"h","s":["Flooding"]},{"k":"p","s":["During the rainy season from May to November, roads outside of Bangui can become impassable. Flooding in Bangui is common and has killed people and destroyed homes. There is a risk of being cut off by floods in areas outside the capital, particularly in northern regions. There is also a risk of flash flooding."]},{"k":"h","s":["Earthquakes"]},{"k":"p","s":["Earthquakes are a risk in the Central African Republic. The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 610600 or 117 and ask for an ambulance."]},{"k":"p","s":["Emergency numbers are unreliable in the Central African Republic. The emergency services are unlikely to respond outside of Bangui."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for the Central African Republic","https://travelhealthpro.org.uk/country/46/central-african-republic#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in the Central African Republic","https://travelhealthpro.org.uk/country/46/central-african-republic"],", including:"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["malaria"]},{"k":"li","s":["cholera"]},{"k":"li","s":["Zika virus"]},{"k":"li","s":["mpox"]},{"k":"h","s":["Ebola"]},{"k":"p","s":["On 15 May the Democratic Republic of Congo Ministry of Health announced an outbreak of Ebola Bundibugyo in the North-Eastern Ituri Province. Read more about the ",["Ebola outbreak on TravelHealth Pro","https://travelhealthpro.org.uk/country/63/democratic-republic-of-the-congo#Outbreaks"]," and see ",["information on Ebola and similar diseases.","https://travelhealthpro.org.uk/factsheet/68/viral-haemorrhagic-fever"]," World Health Organisation (WHO) have ",["declared this a Public Health Emergency of International Concern","https://www.who.int/news/item/17-05-2026-epidemic-of-ebola-disease-in-the-democratic-republic-of-the-congo-and-uganda-determined-a-public-health-emergency-of-international-concern"],"."]},{"k":"p","s":["Due to the outbreak, you may experience heightened health screening at international borders in the region. ",["Check entry requirements","https://www.gov.uk/foreign-travel-advice"]," for the country you’re travelling to or transiting."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in the Central African Republic"]},{"k":"p","s":["There are very few healthcare facilities in the Central African Republic. Facilities in Bangui are very basic. Strikes by government workers have affected medical services and hospitals. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation, including medical evacuation by air ambulance."]},{"k":"p","s":["FCDO has a ",["list of medical providers in the Central African Republic","https://www.gov.uk/government/publications/central-african-republic-medical-facilities-and-practitioners"]," where some staff will speak English."]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in the Central African Republic","https://www.gov.uk/government/publications/living-in-central-african-republic/living-in-central-african-republic#healthcare-in-central-african-republic"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in the Central African Republic"]},{"k":"p","s":["Telephone: 117 (ambulance, fire, police)"]},{"k":"p","s":["or"]},{"k":"p","s":["Ambulance: 610600"]},{"k":"p","s":["Fire: 118"]},{"k":"p","s":["Military police (‘gendarmerie’): 2161 2200"]},{"k":"p","s":["Emergency numbers are unreliable in the Central African Republic. The emergency services are unlikely to respond outside Bangui."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Central%20African%20Republic"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=central%20african%20republic"]," in the Central African Republic"]},{"k":"li","s":["dealing with a ",["death in the Central African Republic","https://www.gov.uk/government/publications/car-bereavement-information-pack"]]},{"k":"li","s":["Being ",["arrested or imprisoned in the Central African Republic","https://www.gov.uk/government/publications/central-african-republic-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/central-african-republic/british-embassy-kinshasa"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/central-african-republic/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":14929,"change":"Addition of information about a declaration of an Ebola outbreak in DRC on 15 May (‘Health page’)."},"https://www.gov.uk/foreign-travel-advice/monaco":{"r":"govuk","at":"2026-11-17T17:03Z","sha":"5bb2ad6534342141efc5a1d6a5d12c6df4873d92a0f0fe5e912562d8d77a57f4","read":"https://www.gov.uk/api/content/foreign-travel-advice/monaco","bytes":37376,"x":"fulltext v1","title":"Monaco travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2012-12-27T00:00:00+00:00","mod":"2025-12-10T13:45:13+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/monaco/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Monaco set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Monaco Embassy in the UK","https://embassy-to-uk.gouv.mc/en"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Monaco follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it may have a date of issue that is more than 10 years ago"]},{"k":"li","s":["have an ‘expiry date’ at least 3 months after the day you plan to leave the Schengen area"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport if you need to","https://www.gov.uk/apply-renew-passport"],"."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["France handles immigration matters for Monaco."]},{"k":"p","s":["You can ",["travel without a visa to the Schengen area","https://www.gov.uk/travel-to-eu-schengen-area"],", which includes Monaco, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days."]},{"k":"p","s":["Make sure you get your passport stamped on entry and exit."]},{"k":"p","s":["If you’re a visitor, border guards will look at your entry and exit stamps to check you have not overstayed the 90-day visa-free limit for the Schengen area."]},{"k":"p","s":["If your passport is missing a stamp, show evidence of when and where you entered or left the Schengen area (for example, boarding passes or tickets) and ask the border guards to add the date and location in your passport."]},{"k":"p","s":["At border control, you may also need to:"]},{"k":"li","s":["show proof of your accommodation, for example, a hotel booking confirmation or proof of address for a second home"]},{"k":"li","s":["show proof of your travel insurance"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"li","s":["prove that you have enough money for your stay – the amount varies depending on your accommodation"]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer, to work or study, for business travel or for other reasons, you must meet the ",["French government’s entry requirements","https://uk.ambafrance.org/Applying-for-a-French-visa-in-the-United-Kingdom"],"."]},{"k":"p","s":["If you’re in Monaco with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit."]},{"k":"p","s":["Read about ",["using a residence permit to enter Monaco","https://monservicepublic.gouv.mc/en/themes/nationality-and-residency/residency/residents/residence-permit-and-travel"],"."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Monaco guide","https://travelhealthpro.org.uk/country/150/monaco#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["France handles customs rules for Monaco. There are strict rules about ",["goods you can take into or out of Monaco","https://www.douane.gouv.fr/fiche/volume-and-value-based-customs-and-tax-allowances"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking food into Monaco"]},{"k":"p","s":["You cannot take ",["meat, milk or products containing them into Monaco","https://ec.europa.eu/food/animals/animalproducts/personal_imports_en"],". There are some exceptions such as powdered baby milk, baby food and special foods or pet feed required for medical reasons."]},{"k":"hs","s":["Taking money into Monaco"]},{"k":"p","s":["Declare cash or travellers cheques if the value is 10,000 euros or more. You will get a certified declaration to show you brought it in with you. If you do not, your money could be seized when you leave."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Monaco"]},{"k":"p","s":["Although there’s no recent history of terrorism in Monaco, attacks cannot be ruled out."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Street crime is rare, but take sensible precautions to protect your passport and valuables."]},{"k":"p","s":["Thefts have happened on trains to and from Monaco, and at Nice airport, particularly at the car rental parks where bags have been stolen while drivers are loading their cars."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Dress code"]},{"k":"p","s":["You could get a fine if you walk around in swimsuits, stripped to the waist, or barefoot, apart from on beaches and in bathing areas."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Swimming"]},{"k":"p","s":["Get local advice before swimming in the sea, especially if you see jellyfish."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Monaco, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s Monaco guide","https://www.rac.co.uk/drive/travel/country/monaco/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["You’ll need to have both the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP."]},{"k":"p","s":["Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 112 from a mobile or 18 from a landline and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Monaco","https://www.travelhealthpro.org.uk/country/150/monaco#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Monaco","https://www.travelhealthpro.org.uk/country/150/monaco"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Monaco"]},{"k":"p","s":["Monaco is not a member of the EU so reciprocal medical arrangements with the EU do not apply."]},{"k":"p","s":["The European Health Insurance Card (EHIC) or UK Global Health Insurance Card (GHIC) are not accepted in Monaco. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment and repatriation."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Monaco"]},{"k":"p","s":["Telephone: 112 on a mobile or 18 on a landline (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding ",["English-speaking lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Monaco"]," in Monaco"]},{"k":"li","s":["dealing with a ",["death abroad","https://www.gov.uk/after-a-death/death-abroad?step-by-step-nav=4f1fe77d-f43b-4581-baf9-e2600e2a2b7a"]]},{"k":"li","s":["being ",["arrested or imprisoned abroad","https://www.gov.uk/guidance/arrested-or-detained-abroad"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/monaco/british-embassy-paris"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/monaco/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":9478,"change":"New information about dual nationals returning to the UK (‘Entry requirements’ page)."},"https://theconversation.com/a-dead-star-is-flashing-radio-waves-every-8-minutes-and-its-partner-looks-a-lot-like-the-sun-294665":{"r":"conversation","at":"2026-11-17T17:03Z","sha":"bdc45b0b9a96e06670f7adc2a7bf9a1dd43fa8b4a1cedee47839fa8b40759315","read":"https://theconversation.com/a-dead-star-is-flashing-radio-waves-every-8-minutes-and-its-partner-looks-a-lot-like-the-sun-294665","bytes":181024,"x":"fulltext v1","title":"A dead star is flashing radio waves every 8 minutes, and its partner looks a lot like the Sun","by":[{"n":"Natasha Hurley-Walker","r":"Radio Astronomer, Curtin University"}],"pub":"2026-11-12T10:06:18Z","mod":"","blocks":[{"k":"p","s":["Since 2022, astronomers have been puzzling over a new kind of cosmic object called ",["long-period radio transients","https://theconversation.com/this-object-in-space-flashed-brilliantly-for-3-months-then-disappeared-astronomers-are-intrigued-175240"],"."]},{"k":"p","s":["These are objects that emit bright flashes of radio waves into space every few minutes to every few hours."]},{"k":"p","s":["Some have been traced back to binary systems of a small, dim cool star called a red dwarf in orbit with a star remnant called a white dwarf."]},{"k":"p","s":["In ",["new research","https://www.nature.com/articles/s41550-026-03016-z"]," published today in Nature Astronomy, we report the first discovery of a different source for one of these enigmatic intermittent broadcasters: it still involves a white dwarf, but also a star much like our own Sun."]},{"k":"h","s":["The search for sources"]},{"k":"p","s":["After the discovery of the first long-period radio transient in 2022, ",["once we had ruled out aliens","https://theconversation.com/a-mysterious-interstellar-radio-signal-has-been-blinking-on-and-off-every-22-minutes-for-over-30-years-205237"],", we went looking for natural explanations."]},{"k":"p","s":["One idea was that they were extremely slow-spinning neutron star pulsars, the collapsed cores of enormous stars which also send out repeating radio flashes. But in theory a neutron star spinning that slowly shouldn’t produce radio waves, so the answer had to be something else."]},{"k":"p","s":["When we started traced these radio signals back to their sources, we made a breakthrough. ",["One of our repeating signals","https://theconversation.com/astronomers-have-pinpointed-the-origin-of-mysterious-repeating-radio-bursts-from-space-244920"]," came from a red dwarf star, probably orbiting a white dwarf (the remnant of a star like our Sun)."]},{"k":"p","s":["Across ",["the handful of long-period transients","https://theconversation.com/mysterious-signals-keep-coming-from-space-we-have-found-their-rosetta-stone-281753"]," whose source stars we can identify, a pattern has emerged: a binary system of a white dwarf and a small, cool red dwarf."]},{"k":"h","s":["A signal from the wrong kind of star"]},{"k":"p","s":["In late 2024, we were looking for new long-period transients using the ",["Murchison Widefield Array","https://www.mwatelescope.org/"]," radio telescope in Western Australia."]},{"k":"p","s":["Using a search method developed by PhD student ",["Csanád Horváth","https://theconversation.com/profiles/csanad-horvath-2545482"],", we spotted something: short flashes of radio waves, arriving like clockwork every 7.9 minutes."]},{"k":"p","s":["Then the flashes stopped. For weeks we saw nothing, and we nearly gave up. But when we plotted every detection and non-detection together, a pattern emerged."]},{"k":"p","s":["The pulses only appear during a window of about six hours, followed by 26 hours without pulses. The most natural explanation is that the system is a binary: two stars orbiting each other once every 32 hours, with the ",["radio pulses only visible when they are lined up in the right way","https://theconversation.com/puzzling-slow-radio-pulses-are-coming-from-space-a-new-study-could-finally-explain-them-272893"],"."]},{"k":"p","s":["The MeerKAT telescope in South Africa pinpointed the source to a tiny patch of sky containing a single faint star. We turned to the Keck telescope in Hawai’i to record the star’s spectrum – the “fingerprint” of its light, which can tell us a lot about the star itself."]},{"k":"p","s":["The result was a surprise: this was not a tiny red dwarf, but a G-type star almost the same mass and temperature as our own Sun."]},{"k":"h","s":["Weighing a star we can’t see"]},{"k":"p","s":["How can we be sure our source isn’t a neutron star after all?"]},{"k":"p","s":["The clue is in the timing. As the pulsing object swings around its orbit, the pulses arrive up to four seconds earlier or later than expected, because the radio waves have further to travel at some points than others. That tells us how large the orbit is."]},{"k":"p","s":["The precise spectrum “fingerprint” of the Sun-like star shows it barely wobbles as the pulsing object orbits around it. This means the Sun-like star must be much heavier than its partner."]},{"k":"p","s":["When we combine the calculation of the size of the orbit, how long each orbit takes, and the spectrum measurements, we can work out that the pulsing object is about two-thirds as heavy as the Sun. That means it’s too light to be a neutron star."]},{"k":"p","s":["We believe the pulsing object is a white dwarf pulsar, the first found in orbit around a Sun-like star."]},{"k":"h","s":["What strange systems are hiding in the dark?"]},{"k":"p","s":["How did this odd couple come to be? We think the star that became the white dwarf must have first swelled into a giant, engulfing its companion, which spiralled inward and shrank the orbit before the giant’s outer layers were ejected."]},{"k":"p","s":["We think systems like this are probably quite common in the universe, but white dwarfs next to bright stars are very hard to see. The glare of the bright star hides the faint white dwarf."]},{"k":"p","s":["Radio pulses, on the other hand, cut through the glare. If more long-period transients turn out to be hiding white dwarfs around bright stars, radio surveys could uncover a whole undiscovered population that optical and X-ray telescopes miss."]},{"k":"p","s":["This is important because some white dwarf binaries are thought to be the ancestors of Type Ia supernovae. Astronomers use these exploding stars as “standard candles” – reference points to measure interstellar distances and the expansion of the universe. Finding these systems could reveal more about this process."]},{"k":"p","s":["With the next generation of radio telescopes, such as the ",["SKA Observatory","https://www.skao.int/en"],", we expect to find many more. And if we can find these objects around many different types of stars, it will give us insights into the lives and deaths of stars like our own Sun, across our galaxy and beyond."]}],"chars":4753},"https://www.gov.uk/foreign-travel-advice/timor-leste":{"r":"govuk","at":"2026-11-17T17:18Z","sha":"3db7ef698b27585d95cd9b71f8fd0b7c0853f43be2c8ca9def52f6df8e9bf25b","read":"https://www.gov.uk/api/content/foreign-travel-advice/timor-leste","bytes":46763,"x":"fulltext v1","title":"East Timor (Timor-Leste) travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-21T00:00:00+00:00","mod":"2025-12-10T12:48:06+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/timor-leste/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Timor-Leste’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Timor-Leste set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Timor-Leste Embassy in the UK","https://www.facebook.com/TimorLesteEmbassyUK/"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Timor-Leste, your passport must have an ‘expiry date’ at least 6 months after the date you arrive and have 2 blank pages."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Timor-Leste for tourism."]},{"k":"p","s":["You will be issued a single-entry tourism visa, valid for up to 30 days, when you arrive at Presidente Nicolau Lobato International Airport in Dili, or Dili seaport. The visa costs 30 US dollars, payable only in cash."]},{"k":"hs","s":["Travelling to Oecussi overland"]},{"k":"p","s":["If you plan to travel overland, rather than by ferry, to the exclave of Oecussi, you will need to apply for a separate visa on arrival. This visa is available at the Wini border checkpoint. Alternatively, you can apply for a visa for Oecussi in advance. To do this, you must show your round-trip ticket and complete the required forms at your nearest Timor-Leste embassy or consulate, or at the ",["Office of the Ministry of the Interior","https://www.migracao.gov.tl/html/sub0104.php"]," in Dili, before you travel."]},{"k":"hs","s":["Entering at the Atambua-Batugade border crossing"]},{"k":"p","s":["If you’re entering Timor-Leste through Indonesia at the Atambua-Batugade border crossing, you can purchase a visa on entry. Alternatively, you can purchase a tourism visa in advance from a Timor-Leste embassy or consulate in either Denpasar or Kupang. These visas are usually single-entry and last for 30 days."]},{"k":"p","s":["See ",["travel advice for Indonesia","https://www.gov.uk/foreign-travel-advice/indonesia"]," for more information."]},{"k":"hs","s":["Extending your tourism visa"]},{"k":"p","s":["You can ",["apply to extend a tourism visa","https://www.migracao.gov.tl/html/sub0301.php"]," for 30 days. If possible, apply at least 15 days in advance of the tourist visa’s expiry date."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Timor-Leste guide","https://travelhealthpro.org.uk/country/68/timor-leste#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Timor-Leste","https://customs.gov.tl/travelers/duty-free-allowances/"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into Timor-Leste"]},{"k":"p","s":["If you’re planning on bringing cash or travellers cheques worth 20,000 US dollars or more you must get authorisation from the Central Bank of Timor-Leste before you arrive."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Timor-Leste"]},{"k":"p","s":["Although there’s no recent history of terrorism in Timor-Leste, attacks cannot be ruled out."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["The security situation in Timor-Leste has improved but there are still underlying tensions, particularly during election periods when the security situation could deteriorate with little warning."]},{"k":"p","s":["Political demonstrations and local unrest occasionally happen. Minor disputes can become violent. Avoid any demonstrations and large crowds, particularly around Tasi Tolu and Comoro in Dili."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Crime such as gang-related violence, robbery and assault are common in Timor-Leste. Burglaries are not common but have happened. There have been instances of unmetered taxis charging tourists extortionate prices."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["You can take steps to reduce your personal risk by:"]},{"k":"li","s":["not displaying expensive items of jewellery"]},{"k":"li","s":["not carrying large sums of money"]},{"k":"li","s":["keeping your accommodation locked at all times"]},{"k":"li","s":["keeping your car doors locked and windows up at all times"]},{"k":"li","s":["not travelling alone or to isolated areas"]},{"k":"li","s":["taking care if you go outside after dark"]},{"k":"li","s":["taking care in areas which are remote and cut off from services"]},{"k":"li","s":["booking taxis through your hotel, and seeking local advice on appropriate fares"]},{"k":"hs","s":["Sexual assault"]},{"k":"p","s":["There have been reports of harassment and violence against travellers, including lewd remarks and indecent exposure. Offenders mostly target women, but may harass men as well. Sexual assault can happen in public places, such as Beach Road in Dili."]},{"k":"p","s":["Travel as a group if you can, including when exercising outdoors. If possible, avoid using public transport or taxis alone at night."]},{"k":"p","s":["See ",["advice for women travelling abroad","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"],"."]},{"k":"hs","s":["Group fights"]},{"k":"p","s":["There is occasional fighting between groups in Timor-Leste, sometimes related to martial arts groups. These incidents often involve stone throwing and occasionally machetes and knives. Most happen at night."]},{"k":"p","s":["Foreign nationals have not been targeted, but leave the area immediately if you’re aware of fighting."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID and travel documents"]},{"k":"p","s":["Carry a copy of the photo page of your passport and entry visa with you in case the authorities ask to see it. Make sure your travel documents are up-to-date and available in case you need to leave at short notice."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Do not get involved with illegal drugs. There are severe penalties if you’re convicted."]},{"k":"hs","s":["Money"]},{"k":"p","s":["Credit cards are accepted for payments by few outlets in Timor-Leste. ATMs, banks, and credit card facilities are not common outside of municipal capitals."]},{"k":"p","s":["There are a few currency exchanges in the country, but exchange rates are poor and sterling may not be accepted. Bring a few small (5 US dollar) notes as larger denomination notes can be difficult to spend. Notes printed before 2009 are usually rejected, but can be changed at the Central Bank in Dili."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Swimming safety"]},{"k":"p","s":["Crocodiles are frequently seen in inland waterways and on the south coast and the eastern region. Occasionally they may be seen at beaches near Dili. Get local advice before going in the water."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Timor-Leste, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You’ll need to have both the ",["correct version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP. If you hire a car in Timor-Leste it’s likely you’ll have to hire a driver as well."]},{"k":"hs","s":["Driving and road conditions"]},{"k":"p","s":["Roads are generally in poor condition and accidents, particularly involving motorbikes and scooters, are common."]},{"k":"p","s":["Main routes are often single-track mountain roads, which can deteriorate quickly and become impassable, particularly during the rainy season from November to April."]},{"k":"p","s":["Outside Dili, travel in convoy whenever possible because of the lack of emergency services, poor road conditions and cars driving without lights at night."]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["There have been incidents of piracy on the waters around Timor-Leste. Consider ",["taking precautions against piracy attacks","https://www.gov.uk/guidance/sea-river-and-piracy-safety"],"."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Rainy season"]},{"k":"p","s":["The rainy season in Timor-Leste normally runs from November to April. Heavy rains can cause flash flooding and landslides. Monitor local and international weather updates from the ",["World Meteorological Organisation","https://severeweather.wmo.int/tc/au/index.html"],". Take extreme care when walking on flooded pavements or roads in Dili. Uncovered manholes can lead to injuries or drowning."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["Earthquakes are a risk in Timor-Leste, although there has not been a significant one since 2005. The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 110, +670 331 1044 or +670 723 3212 and ask for an ambulance."]},{"k":"p","s":["Emergency medical services in Timor-Leste are unreliable. Make your own way to hospital if you can."]},{"k":"p","s":["There may be other numbers for the areas you visit – ask your hotel or the local police."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Timor-Leste","https://travelhealthpro.org.uk/country/68/timor-leste#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["Go to TravelHealthPro to see ",["what health risks you’ll face in Timor-Leste","https://travelhealthpro.org.uk/country/68/timor-leste"],", including:"]},{"k":"li","s":["rabies (Oecusse exclave, Bobonaro and Covalima municipalities, and possibly elsewhere)"]},{"k":"li","s":["chikungunya"]},{"k":"li","s":["dengue"]},{"k":"li","s":["gastroenteritis"]},{"k":"li","s":["typhoid"]},{"k":"li","s":["hepatitis"]},{"k":"li","s":["tuberculosis"]},{"k":"p","s":["Altitude sickness is a risk in parts of Timor-Leste. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Timor-Leste"]},{"k":"p","s":["Medical services in Timor-Leste are limited, particularly outside Dili."]},{"k":"p","s":["In a medical emergency, it’s likely you’ll need to be evacuated to Australia or Singapore. However, medical evacuation is difficult because of the limited number of airlines from Timor-Leste. You should make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Timor-Leste"]},{"k":"p","s":["Ambulance: 110 or +670 331 1044"]},{"k":"p","s":["Fire: 115 or +670 331 0340"]},{"k":"p","s":["Police: 112 or +670 331 1380"]},{"k":"p","s":["Emergency numbers are unreliable in Timor-Leste."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["dealing with a ",["death abroad","https://www.gov.uk/after-a-death/death-abroad"]]},{"k":"li","s":["being ",["arrested or imprisoned abroad","https://www.gov.uk/guidance/arrested-or-detained-abroad"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/timor-leste/british-embassy-jakarta"]," including in an emergency."]},{"k":"p","s":["Emergency consular services for British nationals are provided by the New Zealand Embassy in Dili (24-hour emergency number: +670 7732 1015)."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/timor-leste/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":12992,"change":"New information about dual nationals returning to the UK (‘Entry requirements’ page)."},"https://theconversation.com/ukraine-peace-talks-end-with-no-breakthrough-but-europe-may-be-set-to-return-from-the-cold-296207":{"r":"conversation","at":"2026-11-17T17:32Z","sha":"6b3d7ba3179667a6eabf72064bab5f29353da4fede4b3716950e8f6de2abbd72","read":"https://theconversation.com/ukraine-peace-talks-end-with-no-breakthrough-but-europe-may-be-set-to-return-from-the-cold-296207","bytes":185345,"x":"fulltext v1","title":"Ukraine peace talks end with no breakthrough – but Europe may be set to return from the cold","by":[{"n":"Bo Petersson","r":"Professor of Political Science, Malmö University"}],"pub":"2026-11-12T13:38:57Z","mod":"","blocks":[{"k":"p","s":["The first talks between Russia and Ukraine in nine months have concluded. The most positive thing that can be said about the US-mediated meeting in Abu Dhabi was that the dialogue did not break down and the parties seemed to agree to further meetings."]},{"k":"p","s":["There was also at least one tangible result. ",["Russia","https://theconversation.com/topics/russia-1376"]," and Ukraine ",["agreed","https://www.reuters.com/world/europe/us-russia-ukraine-start-second-day-abu-dhabi-peace-talks-2026-11-11/"]," on a large-scale exchange of prisoners of war, the magnitude of which will be clarified over the coming days. Beyond this, however, there were few signs of progress towards a peace agreement."]},{"k":"p","s":["Despite Ukrainian president Volodymyr Zelensky’s ",["claim","https://www.thetimes.com/world/russia-ukraine-war/article/ukraine-russia-peace-talks-abu-dhabi-progress-zelensky-putin-5mx52v65s"]," that all participants in the negotiation process “genuinely want to achieve a result before 2027”, the most important issues remain unresolved. These include ceasefire terms, the future status of occupied regions and long-term security guarantees for Ukraine."]},{"k":"p","s":["The talks took place against the backdrop of continued fighting on the frontline. Russia’s military currently controls about a fifth of Ukraine, but progress on the battlefield has slowed in 2026 – and has even been reversed – due to ",["Ukrainian successes","https://theconversation.com/operation-vivaldi-success-of-ukraines-counteroffensive-shows-it-has-learned-to-manoeuvre-on-a-drone-filled-battlefield-294197"],"."]},{"k":"p","s":["With the frontline largely static, Moscow keeps ",["striking Ukrainian cities","https://theconversation.com/sodcit-after-battlefield-setbacks-russia-returns-to-destroying-ukraines-morale-294292"]," and energy sites with missiles and drones. In turn, ",["Ukraine has attacked","https://theconversation.com/ukraines-drone-strikes-are-having-an-impact-on-russia-but-russian-leaders-remain-committed-to-war-287812"]," Russian oil refineries and other energy infrastructure."]},{"k":"p","s":["According to reports from Abu Dhabi, Ukraine firmly ",["rejected a proposal","https://www.kyivpost.com/post/89765"]," for it to surrender the entire Donbas region in the east of the country in return for peace. Whether the Russian demand for the Donbas indicates a softening of its claim to the Kherson and Zaporizhzhia regions remains too early to determine."]},{"k":"p","s":["The deadlock remains on other key issues, too. Russia continues to insist that a restructuring of Europe’s security architecture must be put in place before any ceasefire can take effect, to address what it regards as its legitimate security concerns."]},{"k":"p","s":["On the eve of its full-scale invasion in 2022, Russia ",["demanded the withdrawal","https://www.brookings.edu/articles/russias-draft-agreements-with-nato-and-the-united-states-intended-for-rejection/"]," of Nato forces from countries that joined the alliance after 1997. These include the Czech Republic, Hungary, Poland and other eastern European states. If this demand still stands, it is difficult to envisage an end to the war anytime soon."]},{"k":"p","s":["Ukraine, for its part, is bracing itself for ",["another harsh winter","https://www.bbc.co.uk/news/articles/cr1ewpd95d21o"],". It therefore seeks a ceasefire as the starting point for any serious negotiations on peace. This demand, backed by its European supporters, has so far fallen on deaf ears in the Kremlin."]},{"k":"p","s":["This was evidenced by missile strikes that continued even during the peace talks themselves. The coercive nature of Russia’s strategy was further underlined by the fact that six major electricity substations in central Ukraine ",["were reportedly struck","https://kyivindependent.com/russia-strikes-6-major-power-substations-causing-outages-across-ukraine/"]," during the night between the two days of negotiations."]},{"k":"p","s":["Perhaps the most important new point of departure for the Abu Dhabi talks was a new initiative by the Trump administration to tie a peace deal to a broader European security framework. US envoy Jared Kushner, the son-in-law of President Donald Trump, has ",["said this framework","https://x.com/jaredkushner/status/2118535340898025679"]," would provide security guarantees to Ukraine while also meeting Russian security demands."]},{"k":"p","s":["The details of what such a construction would look like are hidden from the public view. But if the recent stances of the Trump administration are of any guidance, those details are likely to be closer to Russian preferences than Ukrainian ones."]},{"k":"p","s":["In recent weeks, Trump has ",["struck a controversial deal","https://theconversation.com/donald-trump-aligns-with-vladimir-putin-yet-again-leaving-ukraine-and-us-relations-with-europe-under-pressure-294119"]," that has allowed Moscow to restore some of its diesel exports, waiving several sanctions in the process. Steve Witkoff, another US presidential envoy, also ",["praised","https://www.politico.com/news/2026/10/22/uk-trashes-witkoff-for-putin-humanitarian-remarks"]," Russian leader Vladimir Putin as a “humanitarian” in late October."]},{"k":"h","s":["Left in the cold"]},{"k":"p","s":["So far, the deep irony seems to be that while the issue of a broader European security architecture is on the table, the European countries supporting Ukraine are denied a place at the negotiating table itself."]},{"k":"p","s":["Even though there were representatives of the EU, Nato, France, Germany, Italy and the UK present in Abu Dhabi, they were not given formal voice in the negotiating process. On the first day of the meeting, Russian foreign minister Sergei Lavrov ",["even sarcastically joked","https://www.aa.com.tr/en/eurasia/lavrov-says-european-officials-can-sit-in-hotel-during-abu-dhabi-trilateral-talks/4118886"]," about letting them sit there in their hotels."]},{"k":"p","s":["If the US continues to scale down its military presence in Europe, as Trump ",["has repeatedly hinted","https://edition.cnn.com/2026/05/14/politics/us-military-troop-numbers-europe-trump"]," it will, responsibility for providing the security guarantees Ukraine will so desperately need after the war will fall largely on the EU and European Nato members."]},{"k":"p","s":["This would again call for giving Europe a voice and presence at the negotiating table, which seems to have been recognised at least by Kushner. After the Abu Dhabi talks concluded, he was ",["reported as saying","https://www.afp.com/en/us-envoys-arrive-russia-putin-meeting-after-ukraine-talks"]," European partners must be at the table in future rounds. He said he would raise the matter with Putin."]},{"k":"p","s":["Europe’s participation in the talks is not a marginal issue, particularly as the position of the US as an honest broker has become debatable, given the tendency of the Trump administration to side with Russia on essential issues. Trump’s ",["recent remark that","https://kyivindependent.com/ukraine-will-likely-end-up-with-a-little-bit-different-shape-after-war-trump-tells-60-minutes/"]," Ukraine might “end up with a little bit different shape” after the war suggests this remains the case."]},{"k":"p","s":["The Abu Dhabi meeting has at least revived negotiations between the two warring parties. But it is far from evident that peace has moved any closer. The most contentious issues remain essentially where they were before the parties convened in the Emirates."]}],"chars":5342},"https://theconversation.com/how-amendment-3-vaccine-mandates-and-school-vouchers-will-shape-florida-under-the-leadership-of-byron-donalds-295720":{"r":"conversation","at":"2026-11-17T17:32Z","sha":"1f3afc36791ed64e252a27790fcfb8ff35944610b7588da9e7ca242a4071f413","read":"https://theconversation.com/how-amendment-3-vaccine-mandates-and-school-vouchers-will-shape-florida-under-the-leadership-of-byron-donalds-295720","bytes":191523,"x":"fulltext v1","title":"How Amendment 3, vaccine mandates and school vouchers will shape Florida under the leadership of Byron Donalds","by":[{"n":"Liv Coleman","r":"Professor of Political Science and International Studies, University of Tampa"}],"pub":"2026-11-05T14:26:38Z","mod":"","blocks":[{"k":"p","s":["In the midst of what pundits are calling a ",["blue tsunami nationwide","https://www.cnn.com/2026/11/04/politics/live-news/midterm-election-congress"],", ",["Florida remained resolutely red","https://www.nytimes.com/interactive/2026/11/03/us/elections/results-florida.html"],", electing Republican Byron Donalds as its first Black governor and sending Republican Ashley Moody back to the U.S. Senate."]},{"k":"p","s":["Donalds ran on a promise to continue the ",["legacy of his predecessor","https://theconversation.com/ron-desantis-2-terms-in-office-fundamentally-altered-floridas-political-landscape-cementing-conservative-policies-through-strategic-control-of-state-institutions-289946"],", Gov. Ron DeSantis."]},{"k":"p","s":["His victory was not as easily won as ",["polls had predicted","https://www.nytimes.com/interactive/polls/florida-governor-election-polls-2026.html"],". In the week leading up to the election, polls put him at 4 points over his opponent, Democrat David Jolly. In the end, Donalds ",["won by 1.3 points","https://www.nytimes.com/interactive/2026/11/03/us/elections/results-florida.html"]," – about 107,000 votes."]},{"k":"p","s":["I’m a ",["political scientist","https://scholar.google.com/citations?user=zTrHGLoAAAAJ&hl=en"]," who has lived in Florida for almost two decades and seen the powers of the governor’s office grow. We can see based on Donalds’ campaign promises the direction in which he plans to lead the state."]},{"k":"h","s":["Amendment 3 shakes things up"]},{"k":"p","s":["Donalds’ term as governor will start with a major change: On Nov. 3, Floridians ",["voted to pass Amendment 3","https://theconversation.com/florida-just-voted-for-lower-property-taxes-and-that-could-mean-cuts-in-government-services-and-new-housing-construction-295716"]," to the state constitution."]},{"k":"p","s":["This will cause a shift in the state’s long-standing commitment to ",["home rule","https://scholarship.stu.edu/faculty_articles/69/"],", the principle that local governments, such as cities and counties, should be able to set policy on local issues."]},{"k":"p","s":["The amendment ",["limits local government spending","https://floridapolitics.com/archives/816005-help-for-rural-coming-if-amendment-3-passes-governor-says/"]," from tax revenue to core categories such as public safety, schools and natural resources. With a lower tax base, some ",["local governments in rural areas","https://floridapolitics.com/archives/816005-help-for-rural-coming-if-amendment-3-passes-governor-says/"]," may not be able to maintain basic services and might need help from the state."]},{"k":"p","s":["DeSantis has ",["called for a special session","https://www.miamiherald.com/news/politics-government/state-politics/article317924418.html"]," to address Amendment 3 before Donalds takes office."]},{"k":"p","s":["DeSantis has said he plans to restrict home rule by stopping local governments from trying to raise revenue ",["through additional taxation at the local level","https://www.miamiherald.com/news/politics-government/state-politics/article317924418.html"],"."]},{"k":"p","s":["Donalds ",["supported the amendment","https://www.wuft.org/politics/2026-10-01/byron-donalds-visits-uf-discusses-dei-and-amendment-3"],", and it will give him and the Legislature the opportunity to redistribute tax funding throughout the state."]},{"k":"p","s":["This election has changed the makeup of the state Legislature, though, with the GOP ",["losing its supermajority","https://www.tampabay.com/news/florida-politics/elections/2026/11/03/florida-midterm-election-results/"]," in the Florida House of Representatives, which requires holding 80 out of the 120 seats. This change in the Legislature could make it more difficult for Donalds to control the agenda in Tallahassee the way DeSantis did during his second term, when he had a supermajority in both houses of the Legislature."]},{"k":"p","s":["Donalds has affirmed that he ",["supports the big steps DeSantis has taken","https://www.tampabay.com/news/florida-politics/elections/2026/09/29/david-jolly-byron-donalds-florida-data-centers-governor/"]," to limit home rule – such as ",["limiting local control over land development","https://www.tallahassee.com/story/news/state/2026/04/14/planning-law-limiting-local-governments-in-florida/89553404007/"]," and ",["removing local elected officials","https://floridaphoenix.com/2023/08/09/desantis-ousts-another-democratic-prosecutor-monique-worrell-of-orange-county/"]," from office – and plans to ",["take executive authority further","https://www.tampabay.com/news/florida-politics/elections/2026/09/29/david-jolly-byron-donalds-florida-data-centers-governor/"],", scheduling more DOGE audits of local government and removing more elected officials as he sees fit."]},{"k":"p","s":["When it comes to data centers, on the other hand, Donalds has said he favors ",["local communities deciding","https://www.tampabay.com/news/florida-politics/elections/2026/09/29/david-jolly-byron-donalds-florida-data-centers-governor/"]," whether to allow them to be built nearby."]},{"k":"h","s":["Florida health policy on vaccine mandates"]},{"k":"p","s":["One of the first choices awaiting Donalds will be whom to appoint as Florida surgeon general, a position ",["created in 2007","https://www.floridahealth.gov/about-us/"],". The position comes with the power to ",["declare public health emergencies","https://floridapolitics.com/archives/473446-lawmakers-ok-bills-to-limit-surgeon-general-emergency-powers/"],", forcibly quarantine people and ",["set vaccine mandates for illnesses such as chickenpox","https://floridatrident.org/repeal-of-vaccine-mandates-faces-legal-challenges/"]," that fall outside the state Legislature’s framework of ",["seven childhood vaccine mandates","https://floridatrident.org/repeal-of-vaccine-mandates-faces-legal-challenges/"],"."]},{"k":"p","s":["As part of his ",["conservative remake of Florida policies","https://theconversation.com/ron-desantis-2-terms-in-office-fundamentally-altered-floridas-political-landscape-cementing-conservative-policies-through-strategic-control-of-state-institutions-289946"],", DeSantis appointed the current surgeon general, ",["Dr. Joseph Ladapo","https://www.floridahealth.gov/about-us/leadership/state-surgeon-general/"],", to the position in 2021. During the COVID-19 pandemic, Ladapo emerged as a leading ",["medical freedom","https://www.ebsco.com/research-starters/consumer-health/health-freedom-movement/"]," advocate and vaccine skeptic."]},{"k":"p","s":["Ladapo ",["opposes all vaccine mandates","https://abcnews.com/Health/florida-surgeon-general-state-moving-end-vaccine-mandates/story?id=125224527"],". He also proposed new Florida health rules in October 2026 to ",["drop mandates for four vaccines","https://floridaphoenix.com/2026/10/08/ladapo-eliminating-vaccine-mandates-isnt-about-science-its-about-parents-rights/"]," required for school attendance, including chickenpox and hepatitis B. Currently, ",["the state allows exemptions","https://www.floridahealth.gov/individual-family-health/immunization/parents-children-and-adolescents/exemption-from-required-immunizations/"]," only for approved religious or medical reasons."]},{"k":"p","s":["The Florida Chapter of the American Academy of Pediatrics ",["opposes the rule change","https://www.fcaap.org/posts/news/florida-pediatricians-testify-against-proposed-rule-weakening-school-immunization-requirements/"]," on public health grounds."]},{"k":"p","s":["Donalds has long ",["opposed vaccine mandates","https://donalds.house.gov/news/email/show.aspx?ID=B5G6AKCJWTTEQ"]," and says that he ",["did not personally receive a COVID-19 vaccine","https://edition.cnn.com/videos/politics/2021/07/27/byron-donalds-florida-coronavirus-vaccine-cuomo-intv-vpx.cnn"],". He ",["supports Ladapo’s proposed rule change","https://www.wusf.org/politics-issues/2026-09-23/donalds-might-retain-joseph-ladapo-as-surgeon-general-jolly-says-hed-fire-him"]," to reduce school vaccination mandates and said during his campaign that he is ",["open to reappointing Ladapo","https://www.wusf.org/politics-issues/2026-09-23/donalds-might-retain-joseph-ladapo-as-surgeon-general-jolly-says-hed-fire-him"]," as surgeon general."]},{"k":"p","s":["The Florida Legislature, however, will limit how far Donalds can push vaccine policy. The ",["Legislature has mandated","https://mynews13.com/fl/orlando/news/2026/08/14/new-federal-vaccine-guidance-raises-questions-for-florida-families-but-school-requirements-remain-unchanged"]," measles and polio vaccines for all K-12 public school students, so getting rid of that requirement would require a change in the law."]},{"k":"h","s":["Universal school vouchers"]},{"k":"p","s":["One of the biggest developments in Florida K-12 education in recent years has been the creation of a system of ",["universal vouchers","https://theconversation.com/floridas-school-choice-program-offers-universal-vouchers-but-cannot-show-systemwide-academic-improvement-283040"]," by DeSantis and the Legislature in 2023. This program allows ",["parents of any income level","https://www.stepupforstudents.org/scholarships/"]," to use ",["US$8,000 in state money on average, based on county of residence","https://go.stepupforstudents.org/hubfs/Scholarship%20Info/FTC-FES-EO-PEP-Award-Amounts.pdf"],", for their children’s private or homeschooling education."]},{"k":"p","s":["The universal voucher program has created intense pressure on the state budget. It cost an ",["estimated $4.5 billion in fiscal year 2026","https://www.tampabay.com/news/education/2026/05/27/vouchers-grow-floridas-budget-will-there-be-added-accountability/"],". State auditors have identified ",["accountability problems","https://mynews13.com/fl/orlando/news/2025/12/04/audit-finds-fl-vouchers-program-has-trouble-tracking-millions"]," in tracking funds through the system. Public schools have faced ",["declining enrollment","https://hechingerreport.org/universal-vouchers-have-public-schools-worried-about-something-new-market-share/"],", with fewer resources to serve the neediest students they cannot turn away."]},{"k":"p","s":["Donalds strongly supports the universal voucher program. He has expressed an interest in making Florida “ ",["the model state for school choice","https://floridatrib.org/2026/07/30/what-byron-and-erika-donalds-gospel-of-school-choice-could-mean-for-florida/"],"” by ",["allowing parents to choose among private educational providers competing in the marketplace","https://www.miaminewtimes.com/news/the-billionaire-trying-to-reinvent-florida-schools-has-a-7-5-million-bet-on-byron-donalds-40565603/"],"."]},{"k":"p","s":["His wife, Erika Donalds, is a former Collier County school board member who operates a ",["network of for-profit charter schools","https://www.miamiherald.com/news/politics-government/election/article317723535.html"]," and ",["advocates nationally for school choice","https://floridatrib.org/2026/07/30/what-byron-and-erika-donalds-gospel-of-school-choice-could-mean-for-florida/"],". Whether the Donaldses will ",["divest from the charter school business","https://www.wlrn.org/government-politics/2026-11-03/byron-donalds-makes-history-as-states-first-black-governor"]," during the governor-elect’s term remains to be seen."]},{"k":"p","s":["Already, the governor-elect has ",["indicated","https://www.miamiherald.com/news/politics-government/state-politics/article317924418.html"]," that he might work with the Legislature to change the way the Florida Education Finance Program funds K-12 schools, allowing districts to spend funds with more flexibility."]},{"k":"p","s":["During his campaign he also proposed a ",["universal scorecard","https://www.yahoo.com/news/politics/articles/teacher-pay-vouchers-candidates-florida-195700038.html"]," for the voucher program so that parents can compare educational data on student performance across different types of schools. Currently, only public schools must provide this data."]},{"k":"p","s":["Donalds can also influence state education policy by ",["appointing the seven members of the Board of Education","https://www.fldoe.org/policy/state-board-of-edu/"]," and then recommending a candidate for ",["commissioner of education","https://www.fldoe.org/about-us/commissioner/"]," for that board to elect. The commissioner and state board oversee the ",["Florida Department of Education","https://www.fldoe.org/"]," and programs from kindergarten through postsecondary education."]},{"k":"p","s":["They board could also implement new eligibility rules for private school vouchers, ",["as the DeSantis administration","https://www.flgov.com/eog/news/press/2023/florida-takes-action-against-four-florida-schools-ties-chinese-communist-party"]," ",["has done","https://www.tallahassee.com/story/news/state/2026/10/15/florida-school-vouchers-could-be-banned-for-some-islamic-schools/91705943007/"]," in the past."]},{"k":"h","s":["The way forward"]},{"k":"p","s":["During his campaign, Donalds attempted to ",["distance himself from President Donald Trump","https://www.yahoo.com/news/politics/articles/m-allowed-own-viewpoint-byron-090000377.html"],", whose policies have proven unpopular even in red states such as Florida."]},{"k":"p","s":["But in his ",["victory speech on the evening of Nov. 3","https://www.youtube.com/watch?v=Qc9qAcp-PCE"],", Donalds proudly announced that he had received a congratulatory call from the president. “Mr. President,” he said to a cheering crowd, “I want you to hear from Florida that we are still red.”"]},{"k":"p","s":["This story is an update of a ",["story published on Oct. 28, 2026","https://theconversation.com/3-major-issues-that-republican-byron-donalds-or-democrat-david-jolly-will-need-to-address-as-floridas-next-governor-293784"],". Read more of ",["our stories about Florida","https://theconversation.com/us/south-florida-miami-news"],"."]}],"chars":6936}};
